# Generated by AI

from collections.abc import Callable
from functools import partial
from math import fsum

from app.core.language import Language, localized
from app.schemas.environmental import WeatherForecast
from app.schemas.indicators import RiskIndicator, RiskLevel, RisksResponse

SOURCE_URL = "https://open-meteo.com/en/docs"
FROST_URL = "https://avisos.inmet.gov.br/56121"
INMET_URL = "https://www.gov.br/mdr/pt-br/centrais-de-conteudo/publicacoes/protecao-e-defesa-civil-sedec/guiapraticodesastres.pdf"
EMBRAPA_SOY_URL = "https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/1123928/1/SP-17-2020-online-1.pdf"
EMBRAPA_CORN_URL = "https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/748759/1/Milho-Plantio.pdf"
SUGARCANE_HEAT_URL = "https://portal.inmet.gov.br/uploads/publicacoesDigitais/agrometeorologia_dos_cultivos.pdf#page=122"
HEAT_CRITERIA = {
    "soybean": (40, EMBRAPA_SOY_URL),
    "corn": (35, EMBRAPA_CORN_URL),
    "sugarcane": (35, SUGARCANE_HEAT_URL),
}
LIMITATION = "Triagem regional baseada em previsão. Para avisos oficiais, consulte o INMET."


def risk_limitation(language: Language) -> str:
    return localized(
        language, LIMITATION, "Regional screening based on forecasts. Consult INMET for official alerts.",
    )


def threshold_indicator(
    forecast: WeatherForecast, kind: str, field: str, unit: str,
    reducer: Callable, classify: Callable[[float], RiskLevel],
    criterion: str, limitations: list[str], criteria_url: str | None, language: Language,
) -> RiskIndicator:
    samples = [
        (getattr(day, field), day.date)
        for day in forecast.daily if getattr(day, field) is not None
    ]
    metadata = forecast.daily_metrics.get(field)
    if metadata is None or metadata.unit != unit:
        samples = []
    value, when = reducer(samples) if samples else (None, None)
    level = classify(value) if value is not None else "insufficient_data"
    if level == "low" and len(samples) < forecast.requested_days:
        level = "insufficient_data"
    if level == "insufficient_data":
        summary = localized(language, "Evidência insuficiente no período analisado.", "Insufficient data for the period assessed.")
    else:
        summary = localized(
            language, f"Indicador calculado com {len(samples)} de {forecast.requested_days} dias.",
            f"Calculated using {len(samples)} of {forecast.requested_days} days.",
        )
    return RiskIndicator(
        type=kind, level=level, justification=f"{summary} {criterion}", reference_date=when,
        values={field: value}, limitations=[risk_limitation(language), *limitations], criteria_url=criteria_url,
    )


def water_deficit(forecast: WeatherForecast, language: Language) -> RiskIndicator:
    tr = partial(localized, language)
    soil = next((
        metric.value for metric in forecast.current.soil_moisture
        if metric.depth_cm == (3, 9) and metric.unit == "m³/m³" and metric.status == "available"
    ), None)
    rain = [day.precipitation for day in forecast.daily if day.precipitation is not None]
    et0 = [
        day.reference_evapotranspiration
        for day in forecast.daily if day.reference_evapotranspiration is not None
    ]
    complete = (
        len(rain) == len(et0) == forecast.requested_days
        and all(
            field in forecast.daily_metrics and forecast.daily_metrics[field].unit == "mm"
            for field in ("precipitation", "reference_evapotranspiration")
        )
    )
    rain_total = fsum(rain) if complete else None
    et0_total = fsum(et0) if complete else None
    balance = rain_total - et0_total if complete else None
    if balance is None or forecast.requested_days < 5 or soil is None:
        level = "insufficient_data"
        justification = tr("A triagem requer pelo menos cinco dias completos de chuva e ET₀, além de umidade estimada do solo.", "Screening requires at least five complete days of rainfall and ET₀ data, plus estimated soil moisture.")
    elif balance < 0:
        level = "moderate"
        justification = tr("A chuva prevista é inferior à evapotranspiração de referência no período.", "Forecast rainfall is lower than reference evapotranspiration over the period.")
    else:
        level = "low"
        justification = tr("A chuva acumulada prevista iguala ou supera a evapotranspiração de referência no período.", "Total forecast rainfall meets or exceeds reference evapotranspiration over the period.")
    return RiskIndicator(
        type="water_deficit", level=level, justification=justification, criteria_url=SOURCE_URL,
        values={
            "precipitation_mm": round(rain_total, 2) if rain_total is not None else None,
            "reference_et0_mm": round(et0_total, 2) if et0_total is not None else None,
            "precipitation_minus_et0_mm": round(balance, 2) if balance is not None else None,
            "soil_moisture_3_to_9cm_m3_m3": soil,
        },
        limitations=[
            tr("A diferença chuva menos ET₀ caracteriza demanda atmosférica de referência.", "Rainfall minus ET₀ describes the balance against reference atmospheric demand."),
            tr("A umidade superficial contextualiza o sinal. O balanço da zona radicular exige dados da cultura e do solo.", "Near-surface moisture provides context. A root-zone water balance requires crop and soil data."),
        ],
    )


def analyze_risks(
    forecast: WeatherForecast, crop_id: str | None = None, language: Language = "pt",
) -> RisksResponse:
    tr = partial(localized, language)
    heat_limit, heat_url = HEAT_CRITERIA.get(crop_id, (None, None))
    indicators = [
        threshold_indicator(
            forecast, "frost", "temperature_min", "°C", min,
            lambda t: "high" if t <= 0 else "moderate" if t <= 3 else "low",
            tr("A triagem sinaliza mínimas do ar até 3 °C e dá destaque a valores até 0 °C.", "Daily minimum air temperatures of 3 °C or below are flagged, with higher risk at 0 °C or below."),
            [tr("A formação de geada depende do microclima e da temperatura junto à superfície.", "Frost formation depends on the microclimate and near-surface temperatures.")], FROST_URL, language,
        ),
        threshold_indicator(
            forecast, "heat", "temperature_max", "°C", max,
            lambda t: (
                "insufficient_data" if heat_limit is None else "high" if t > heat_limit else "low"
            ),
            tr(
                f"A triagem sinaliza máxima diária prevista acima de {heat_limit} °C para a cultura selecionada.",
                f"Forecast daily highs above {heat_limit} °C are flagged for the selected crop.",
            )
            if heat_limit is not None else tr("Há critérios de calor disponíveis para soja, milho e cana-de-açúcar.", "Heat thresholds are available for soybean, corn, and sugarcane."),
            [tr("O efeito térmico depende do estágio, da duração da exposição e da cultivar.", "Heat effects depend on growth stage, exposure duration, and cultivar.")], heat_url, language,
        ),
        threshold_indicator(
            forecast, "heavy_rain", "precipitation", "mm", max,
            lambda v: "high" if v > 100 else "moderate" if v >= 50 else "low",
            tr("Triagem pelo maior acumulado diário a partir de 50 mm, com destaque acima de 100 mm.", "Daily rainfall of at least 50 mm is flagged, with higher risk above 100 mm."),
            [tr("Picos horários e condições locais exigem avaliação própria.", "Hourly rainfall peaks and local conditions require a separate assessment.")], INMET_URL, language,
        ),
        threshold_indicator(
            forecast, "strong_wind", "wind_gusts_max", "km/h", max,
            lambda v: "high" if v > 100 else "moderate" if v >= 60 else "low",
            tr("Triagem pela maior rajada diária a partir de 60 km/h, com destaque acima de 100 km/h.", "Daily wind gusts of at least 60 km/h are flagged, with higher risk above 100 km/h."),
            [tr("A exposição local depende do relevo e da cobertura.", "Local exposure depends on terrain and ground cover.")], INMET_URL, language,
        ),
        water_deficit(forecast, language),
    ]
    assessed = sum(item.level != "insufficient_data" for item in indicators)
    if forecast.status == "provider_error":
        status = "provider_error"
    elif assessed == len(indicators):
        status = "available"
    else:
        status = "partial" if assessed else "insufficient_data"
    dates = [day.date for day in forecast.daily]
    return RisksResponse(
        location=forecast.location, status=status, period_start=min(dates, default=None),
        period_end=max(dates, default=None), requested_days=forecast.requested_days,
        crop_id=crop_id, indicators=indicators, limitations=[risk_limitation(language)],
    )
